export default {
  description: "Read CO-OPS's verified values again under its verified flags",
  steps: [
    ...YEARS.map(([year, stations]) => ({
      ingest: `backfill coops ${stations} ${year} ${year + 1} --refetch`,
      timeout: 240,
    })),
    {
      check:
        "four verified months hold no value suspect at the source, and two hold the values CO-OPS inferred as interpolated",
      async verify(store) {
        const month = async (id: string, year: number, month: number) => {
          const rows = await readObservations(seriesPath(store, "levels", "coops", id, year));
          const inMonth = rows.filter((r) => new Date(r.time).getUTCMonth() === month - 1);
          if (!inMonth.length) throw new Error(`coops/${id} ${year}-${month}: no levels`);
          // A row with no source flag was written before the store kept one, so the refetch didn't reach it.
          if (inMonth.some((r) => r.source_flag === undefined))
            throw new Error(`coops/${id} ${year}-${month}: levels with no source flag`);
          return inMonth;
        };
        for (const [id, year, m] of [
          ["8776604", 2024, 3],
          ["8721843", 2022, 5],
          ["8775792", 2019, 11],
          ["8777812", 2019, 11],
        ] as const) {
          const suspect = (await month(id, year, m)).filter((r) => r.source_flag === Flag.suspect);
          if (suspect.length)
            throw new Error(
              `coops/${id} ${year}-${m}: ${suspect.length} levels suspect at the source`,
            );
        }
        for (const [id, year, m] of [
          ["8454578", 2015, 7],
          ["8722588", 2008, 5],
        ] as const) {
          if (!(await month(id, year, m)).some((r) => r.source_flag === Flag.interpolated))
            throw new Error(`coops/${id} ${year}-${m}: no level interpolated at the source`);
        }
      },
    },
  ],
} satisfies Migration;
